using System;
using System.IO;
using System.Linq;
using System.Reflection;
using UnityEngine;
namespace FrontierAtlas.Editor
{
    public static class FactoryNetworkValidation
    {
        private static int checks;
        private static void Check(bool ok,string text){if(!ok)throw new InvalidOperationException("RED INDUSTRIAL: "+text);checks++;}
        private static TerritorySimulation Fixture(bool water=false)
        {var g=(TerritorySimulation)typeof(IndustrialDefenceValidation).GetMethod("Fixture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{water});g.LimitFrameWork=false;return g;}
        private static void Tick(TerritorySimulation g,float seconds){for(int i=0;i<Mathf.CeilToInt(seconds/.1f);i++)g.Step(.1f);}
        private static Building Build(TerritorySimulation g,int owner,int x,int y,BuildingKind kind)
        {int c=g.World.At(x,y);Check(g.Construct(owner,c,kind).success,"Construcción válida: "+kind+" "+x+","+y);return g.BuildingAt(c);}
        private static bool Linked(TerritorySimulation g,int factory,int target)=>g.TradeRoutes.Any(r=>!r.naval&&((r.fromBuilding==factory&&r.toBuilding==target)||(r.fromBuilding==target&&r.toBuilding==factory)));
        public static void Run()
        {
            checks=0;var g=Fixture();int f=g.PlayerFaction;g.Rules.factoryConnectionRadius=75;var factory=Build(g,f,70,70,BuildingKind.Factory);
            var targets=new System.Collections.Generic.List<Building>();foreach(var p in new[]{new Vector2Int(30,30),new Vector2Int(60,30),new Vector2Int(100,30),new Vector2Int(110,60),new Vector2Int(30,65),new Vector2Int(30,100),new Vector2Int(65,110),new Vector2Int(100,110),new Vector2Int(78,70)})targets.Add(Build(g,f,p.x,p.y,BuildingKind.City));
            targets.Add(Build(g,f,20,16,BuildingKind.Port));targets.Add(Build(g,f,110,16,BuildingKind.Port));var outside=Build(g,f,8,120,BuildingKind.City);Tick(g,25);
            Check(targets.All(b=>Linked(g,factory.id,b.id)),"Conecta automáticamente once ciudades/puertos, incluido el cercano de ocho celdas");Check(!Linked(g,factory.id,outside.id),"Respeta el radio circular exterior");Check(g.TradeRoutes.Where(r=>!r.naval).All(r=>r.fromBuilding==factory.id),"Nuevas líneas terrestres nacen de una fábrica");
            var ids=g.TradeRoutes.Where(r=>!r.naval).Select(r=>r.id).OrderBy(n=>n).ToArray();Tick(g,600);Check(g.TradeRoutes.Where(r=>!r.naval).Select(r=>r.id).OrderBy(n=>n).SequenceEqual(ids),"Diez minutos de simulación conservan las mismas rutas sin recrearlas");Check(g.Ledgers[f].landTrade>0,"Red estable genera entregas reales");
            Check(g.Construct(f,factory.cell,BuildingKind.Factory).success,"Mejora de fábrica disponible");Tick(g,2);Check(ids.All(id=>g.TradeRoutes.Any(r=>r.id==id)),"Mejora no desconecta líneas");Tick(g,5);Check(targets.All(b=>Linked(g,factory.id,b.id)),"Mejora terminada conserva toda la red");
            var saved=TerritorySimulation.RestoreCampaign(g.World,g.CaptureCampaign());saved.LimitFrameWork=false;Tick(saved,30);Check(ids.All(id=>saved.TradeRoutes.Any(r=>r.id==id)),"Guardar/cargar v5 conserva identidad de rutas");
            var second=Build(g,f,100,80,BuildingKind.Factory);Tick(g,20);Check(targets.Where(b=>Vector2.Distance(new Vector2(b.cell%256,b.cell/256),new Vector2(100,80))<=75).All(b=>Linked(g,second.id,b.id)),"Dos fábricas comparten ciudades sin exclusividad");
            var foreign=Build(g,0,145,70,BuildingKind.City);Tick(g,15);Check(Linked(g,factory.id,foreign.id),"Incluye el borde exacto del alcance");int route=g.TradeRoutes.First(r=>r.fromBuilding==factory.id&&r.toBuilding==foreign.id).id;int deliveries=g.TradeDeliveries.Count(d=>d.destination==foreign.id);g.SetEmbargo(f,0,true);Tick(g,30);
            Check(g.TradeRoutes.Any(r=>r.id==route)&&g.TradeDeliveries.Count(d=>d.destination==foreign.id)==deliveries,"Embargo suspende entregas sin borrar carretera");g.SetEmbargo(f,0,false);Tick(g,90);Check(g.TradeRoutes.Any(r=>r.id==route)&&g.TradeDeliveries.Any(d=>d.destination==foreign.id&&d.time>g.ElapsedTime-90),"Levantar embargo reactiva la misma conexión");
            int removed=targets[0].id;g.DestroyBuilding(targets[0],-1);Tick(g,5);Check(!g.TradeRoutes.Any(r=>r.fromBuilding==removed||r.toBuilding==removed),"Destrucción retira únicamente enlaces del edificio perdido");var rebuilt=Build(g,f,30,30,BuildingKind.City);Tick(g,15);Check(Linked(g,factory.id,rebuilt.id),"Edificio reconstruido se conecta automáticamente");
            g.PreviewFactoryConnections(f,g.World.At(70,85));Tick(g,8);Check(g.TradePreview.Count>3&&g.TradePreview.All(p=>!p.pending),"Previsualización completa se procesa con presupuesto acotado");
            for(int i=0;i<80;i++){g.PreviewFactoryConnections(f,g.World.At(70,85));g.Step(.1f);}Check(g.TradePreview.All(p=>!p.pending),"Mantener el cursor no reinicia ni deja incompleta la previsualización");
            var detour=Fixture();f=detour.PlayerFaction;for(int y=16;y<=110;y++)detour.Obstacles.Add(detour.World.At(55,y));var df=Build(detour,f,40,30,BuildingKind.Factory);var dc=Build(detour,f,80,30,BuildingKind.City);Tick(detour,30);Check(Linked(detour,df.id,dc.id)&&detour.TradeRoutes.Any(r=>!r.naval&&r.length>120),"Desvío terrestre largo no borra una conexión dentro del radio");
            var neutral=Fixture();f=neutral.PlayerFaction;for(int y=16;y<128;y++)for(int x=55;x<=65;x++){int c=neutral.World.At(x,y);if(neutral.Owners[c]==f){neutral.Owners[c]=TerritorySimulation.Neutral;neutral.TerritoryCounts[f]--;}}neutral.CapitalCells[f]=neutral.World.At(40,60);neutral.RebuildCampaignIndexes();var nf=Build(neutral,f,40,60,BuildingKind.Factory);var nc=Build(neutral,f,80,60,BuildingKind.City);Tick(neutral,15);Check(Linked(neutral,nf.id,nc.id),"Conecta por tierra neutral libre sin exigir ocupar un corredor");
            var sea=Fixture(true);f=sea.PlayerFaction;var sf=Build(sea,f,110,60,BuildingKind.Factory);var sc=Build(sea,f,140,60,BuildingKind.City);Tick(sea,20);Check(!Linked(sea,sf.id,sc.id),"No construye vías sobre mar");
            var blocked=Fixture();f=blocked.PlayerFaction;for(int y=16;y<128;y++)for(int x=55;x<=65;x++){int c=blocked.World.At(x,y);if(blocked.Owners[c]==f){blocked.Owners[c]=0;blocked.TerritoryCounts[f]--;blocked.TerritoryCounts[0]++;}}blocked.CapitalCells[f]=blocked.World.At(40,60);blocked.RebuildCampaignIndexes();blocked.SetEmbargo(f,0,true);var bf=Build(blocked,f,40,60,BuildingKind.Factory);var bc=Build(blocked,f,80,60,BuildingKind.City);Tick(blocked,15);Check(Linked(blocked,bf.id,bc.id)&&blocked.Ledgers[f].landTrade==0,"Línea física completa incluso con tránsito bloqueado, sin cobrar oro indebido");blocked.SetEmbargo(f,0,false);Tick(blocked,30);Check(blocked.Ledgers[f].landTrade>0,"Abrir tránsito activa la conexión física existente");
            var income=Fixture();f=income.PlayerFaction;income.Rules.tacticalPassiveIncome=1800;double gold=income.Gold[f];Tick(income,10);Check(Math.Abs(income.Gold[f]-gold-18000)<.01&&Math.Abs(income.Ledgers[f].passive-18000)<.01&&income.IncomeRate(f)==1800,"1800 de oro/s reales sin ciudades ni fábricas");income.Paused=true;Tick(income,10);Check(Math.Abs(income.Gold[f]-gold-18000)<.01,"Pausa detiene ingresos pasivos");income.Paused=false;income.Troops[f]=0;Check(Mathf.Abs(income.ReinforcementRate(f)-23.328f)<.0001f,"Reclutamiento nuevo es 80% mayor que 12,96/s");
            var ownership=Fixture();f=ownership.PlayerFaction;Build(ownership,f,40,60,BuildingKind.Factory);Build(ownership,f,80,60,BuildingKind.City);Tick(ownership,20);Check(ownership.Ledgers[f].landTrade>0,"Ruta utilizada antes de cambiar el dueño de una celda");Check(ownership.ProposeCampaign(f,0,ProposalKind.Treaty,new NegotiationTerms{compact=CompactKind.FreeTrade,sourceTerritory=new[]{ownership.World.At(59,60)}}).success&&ownership.AnswerCampaign(0,ownership.Affairs.proposals.Last().id,true).success,"Cesión canónica de una celda del camino");ownership.SetEmbargo(f,0,true);double prior=ownership.Ledgers[f].landTrade;Tick(ownership,20);Check(ownership.Ledgers[f].landTrade==prior,"Índice de propietarios invalida caché y bloquea cobros tras cesión y embargo");ownership.SetEmbargo(f,0,false);Tick(ownership,20);Check(ownership.Ledgers[f].landTrade>prior,"Índice permite recuperar el comercio sin reconstruir la línea");
            string output=Environment.GetEnvironmentVariable("FRONTIER_OUTPUT")??Path.GetFullPath("Builds");string legacy=Path.Combine(output,"strategy-stress.snapshot");bool migrated=false;
            if(File.Exists(legacy)){var bytes=File.ReadAllBytes(legacy);var world=CampaignFiles.CompatibleWorld(new WorldGrid(FrontierPrototype.MapWidth,FrontierPrototype.MapHeight,4206),bytes);var old=TerritorySimulation.RestoreCampaign(world,bytes);Check(old.Rules.tacticalPassiveIncome==1800&&old.Strategy!=null,"Campaña v4 real recibe ingreso pasivo y conserva estrategia");migrated=true;}
            File.WriteAllText(Path.Combine(output,"factory-network-validation.json"),"{\"passed\":true,\"assertions\":"+checks+",\"legacyV4\":"+migrated.ToString().ToLowerInvariant()+"}");Debug.Log("FACTORY_NETWORK_OK checks="+checks);
        }
    }
}
